DECLARE @ID_ba698667 UNIQUEIDENTIFIER,
@Name_ba698667 NVARCHAR(255),
@Description_ba698667 NVARCHAR(MAX),
@Instructions_ba698667 NVARCHAR(MAX),
@Status_ba698667 NVARCHAR(20),
@Category_ba698667 NVARCHAR(100),
@IconClass_ba698667 NVARCHAR(100),
@Color_ba698667 NVARCHAR(50),
