SET
  @Category_f3da12e8 = N'Research'
SET
  @IconClass_f3da12e8 = N'fa-solid fa-globe'
SET
  @Color_f3da12e8 = N'#2563EB'
SET
  @CreatedByUserID_f3da12e8 = 'ECAFCCEC-6A37-EF11-86D4-000D3A4E707E' EXEC [${flyway:defaultSchema}].spCreateAISkill @ID = @ID_f3da12e8,
